-- Centros de salud y hospitales PÚBLICOS de Colombia (REPS MinSalud, corte mar-2026)
-- Coordenadas: OpenStreetMap cuando hubo coincidencia; si no, centroide del municipio (DANE DIVIPOLA)
CREATE TABLE CENTRO_SALUD (
  ID_CENTRO        NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  COD_HABILITACION VARCHAR2(20) UNIQUE,
  NOMBRE_SEDE      VARCHAR2(300) NOT NULL,
  PRESTADOR        VARCHAR2(300),
  TIPO             VARCHAR2(40),
  ES_ESE           CHAR(2),
  DEPARTAMENTO     VARCHAR2(80),
  MUNICIPIO        VARCHAR2(80),
  COD_DIVIPOLA     CHAR(5),
  DIRECCION        VARCHAR2(300),
  TELEFONO         VARCHAR2(300),
  LATITUD          NUMBER(9,6) NOT NULL,
  LONGITUD         NUMBER(9,6) NOT NULL,
  PRECISION_COORD  VARCHAR2(40)
);

COMMIT;
